const genId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const raw = $json.choices[0].message.content;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const data = JSON.parse(raw.substring(start, end + 1).replace(/[\n\r\t]/g, " "));

const num = (v) => parseFloat(v?.toString().replace(/[^\d.-]/g, '')) || 0;

// 1. On récupère les lignes
const rawLines = data.articles || data.lines || data.lignes_articles || [];

// 2. Calcul du total théorique à partir des lignes pour double-check
const calculatedTotalHTFromLines = rawLines.reduce((acc, l) => {
    const qty = num(l.quantite || l.quantity);
    const pu = num(l.prix_u || l.unit_price_ht);
    return acc + (qty * pu);
}, 0);

// 3. Extraction du total lu par l'IA
const extractedTotalHT = num(data.total_ht || data.totaux?.montant_ht);

return {
    invoice: {

        company_id: "COMP01",
        contact_id: "CONT01",
        direction: 'purchase',
        number: data.number || data.header?.numero_facture || data.numero_facture,
        issue_date: data.issue_date || data.header?.date || data.date,
        due_date: data.due_date || data.header?.date || data.date,
        // On prend le total de l'IA, ou le calcul si l'IA a oublié
        subtotal_ht: extractedTotalHT || calculatedTotalHTFromLines,
        total_ht: extractedTotalHT || calculatedTotalHTFromLines,
        total_tva: num(data.total_tva || data.totaux?.montant_tva),
        total_ttc: num(data.total_ttc || data.totaux?.total_ttc) || (calculatedTotalHTFromLines * 1.20),
        currency: data.currency || data.totaux?.devise || "MAD",
        supplier_name: data.supplier_name || data.header?.fournisseur || data.fournisseur,
        supplier_ice: data.supplier_ice || data.header?.ice_fournisseur,
        client_name: data.client_name || data.header?.client,
        client_ice: data.client_ice || data.header?.client_ice,

        // --- NOUVEAUX CHAMPS DE VÉRIFICATION ---
        verification_total_ht: calculatedTotalHTFromLines,
        is_total_valid: Math.abs(calculatedTotalHTFromLines - extractedTotalHT) < 0.1
    },
    lines: rawLines.map((l, idx) => {
        const qty = num(l.quantite || l.quantity);
        const pu = num(l.prix_u || l.unit_price_ht);
        const lineHT = qty * pu;
        return {
            position: idx + 1,
            code_article: l.code || l.code_article,
            description: l.description || l.designation,
            quantity: qty,
            unit_price_ht: pu,
            line_total_ht: lineHT,
            line_total_ttc: lineHT * 1.20
        };
    })
};

