const newItems = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const images = [];

  // CAS 1 : PDF converti par Cloudmersive (JSON)
  if (item.json.JpgResultPages && item.json.JpgResultPages.length > 0) {
    for (const page of item.json.JpgResultPages) {
       images.push({
         name: `page_${page.PageNumber}.jpg`,
         mimeType: 'image/jpeg',
         data: page.Content // Déjà en base64 string
       });
    }
  } 
  // CAS 2 : Image binaire directe (Binaire venant du Switch/Photo)
  else if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const binaryData = item.binary[key];
      // On utilise l'helper getBinaryDataBuffer pour extraire le binaire réel
      const buffer = await this.helpers.getBinaryDataBuffer(i, key);
      const base64 = buffer.toString('base64');

      images.push({
        name: binaryData.fileName || 'image.jpg',
        mimeType: binaryData.mimeType,
        data: base64
      });
    }
  }

  newItems.push({
    json: {
      images: images,
      count: images.length
    }
  });
}

return newItems;

