const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => (c == 'x' ? Math.random() * 16 | 0 : (Math.random() * 16 | 0 & 0x3 | 0x8)).toString(16));

const raw = $json.choices[0].message.content;
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const rawData = JSON.parse(raw.substring(start, end + 1).replace(/[\n\r\t]/g, " "));

const num = (v) => parseFloat(v?.toString().replace(/[^\d.-]/g, '')) || 0;

return (rawData.invoices || [rawData]).map(data => {
    const invId = uuid();
    const rawLines = data.articles || [];

    // Taux de TVA par défaut
    const tvaStr = data.totaux?.tva_taux || "20%";
    const tvaRate = num(tvaStr) / 100; 

    // 1. Calcul des lignes (pour les articles)
    const lines = rawLines.map((l, idx) => {
        const qty = num(l.quantite);
        const pu = num(l.prix_u);
        const remise = num(l.remise_pourcent) / 100;
        const l_tva = num(l.tva_taux || tvaStr) / 100;
        const lineHT = (qty * pu) * (1 - remise);

        return {
            id: uuid(),
            invoice_id: invId,
            position: idx + 1,
            code_article: l.code,
            description: l.designation,
            quantity: qty,
            unit_price_ht: pu,
            line_total_ht: lineHT,
            line_total_ttc: lineHT * (1 + l_tva),
            tva_rate: num(l.tva_taux || tvaStr)
        };
    });

    // 2. RÉCUPÉRATION DES TOTAUX ÉCRITS SUR L'IMAGE (par l'IA)
    const totalHT_IA = num(data.totaux?.montant_ht);
    const totalTVA_IA = num(data.totaux?.montant_tva);
    const totalTTC_IA = num(data.totaux?.total_ttc);

    // 3. CALCUL DE SÉCURITÉ (en cas d'oubli de l'IA)
    const totalHT_Calc = lines.reduce((acc, l) => acc + l.line_total_ht, 0);
    const totalTTC_Calc = lines.reduce((acc, l) => acc + l.line_total_ttc, 0);

    return {
        invoice: {
            id: invId,
            company_id: "COMP01",
            contact_id: "CONT01",
            direction: 'purchase',
            number: data.header?.numero_facture || data.numero_facture || "SANS_NUMERO",
            issue_date: data.header?.date || data.date,

            // --- MODIFICATION ICI : PRIORITÉ À L'IMAGE ---
            total_ht: totalHT_IA || totalHT_Calc,
            total_tva: totalTVA_IA || (totalTTC_Calc - totalHT_Calc),
            total_ttc: totalTTC_IA || totalTTC_Calc,
            // --------------------------------------------

            currency: data.totaux?.devise || "MAD",
            supplier_name: data.header?.fournisseur || data.fournisseur,
            supplier_ice: data.header?.ice_fournisseur
        },
        lines: lines
    };
});
